#include "vin_private.h"
#include "cmd.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/
                              
/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/

Boolean vin_save (const Vin vin)        
{          
  if(!vin_info.vin.is_valid)
    {
      memcpy (vin_info.vin.code , vin , VIN_SIZE) ;
      
      vin_info.vin.is_valid = !!(nvfs_wr(nvfs_vin, &vin_info.vin.code) == NVFS_OK) && cmd_q_insert(INPUT_VIN_IS_DONE , COMMAND_INSERT_TIMEOUT) ;

      #if DBG_VIN == 1        
        if(vin_info.vin.is_valid)
        {
          dbg_tx_text ("\nVin Save Done") ; 
        }
        else
        {
           dbg_tx_text ("\nVin Save Fail") ; 
        }
            
                
      #endif       
    }
  else
  {
      #if DBG_VIN == 1
        dbg_tx_text ("\nVin Already Save") ;
      #endif       
  }      
     
  return vin_info.vin.is_valid ;
}


